function renderLedger(){
 const profile=$('unitProfile'),u=ordersOpen?G.getUnit(state):null,r=rocketSelected?state.rocket:null,c=state.cannons.find(v=>v.id===cannonSelected);
 if(u?.role==='wizard'){const p=G.profile(u),keys=['M','WS','BS','S','T','W','I','A','Ld'];profile.innerHTML=`<div class="ledger-heading"><span>CHARACTER PROFILE</span><strong>${P.unitName(u)}</strong><small>${u.wounds} / 2 W</small></div><table><thead><tr><th>Model</th>${keys.map(k=>`<th>${k}</th>`).join('')}</tr></thead><tbody><tr><th>${u.name}</th>${keys.map(k=>`<td>${statText(u,k)}</td>`).join('')}</tr></tbody></table><p class="profile-note">${G.equipment(u)} · Level ${u.level} ${(G.LORES[u.lore]??G.LORES.battle).name} · ${u.spells.map(k=>G.SPELLS[k]?.name??k).join(', ')}</p>`;}else if(u){const p=G.profile(u),keys=['M','WS','BS','S','T','W','I','A','Ld'],champion=u.faction==='orc'?'Orc Boss':u.role==='missile'?'Sergeant':'Champion',rows=[['Ordinary',''],[champion,'C'],['Standard Bearer','S'],['Musician','M']];profile.innerHTML=`<div class="ledger-heading"><span>UNIT PROFILE</span><strong>${P.unitName(u)}</strong><small>${G.aliveCount(u)} / ${G.startingModels(u)}</small></div><table><thead><tr><th>Model</th>${keys.map(k=>`<th>${k}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,badge],i)=>`<tr><th>${badge?`<span class="profile-badge">${badge}</span>`:''}${label}</th>${keys.map(k=>{const value=p[k]+(i===1&&(k==='A'||k==='BS'&&u.role==='missile'&&u.faction==='empire'||k==='Ld'&&u.faction==='orc')?1:0);const printed=G.baseProfile(u)[k]+(value-p[k]);return `<td class="${value!==p[k]?'characteristic-diff':''}">${value}${printed!==value?' ('+printed+')':''}</td>`;}).join('')}</tr>`).join('')}</tbody></table><p class="profile-note">${G.equipment(u)} · Standard: +1 combat result · Musician: wins tied combat</p>`;}
 else if(r){profile.innerHTML=`<div class="ledger-heading"><span>UNIT PROFILE</span><strong>Deathshrieker Rocket Launcher</strong><small>${r.wounds}/3 W · ${r.crew} crew</small></div><p>War machine · T6 · Demolition or Incendiary rocket</p>`;}
 else if(c){profile.innerHTML=`<div class="ledger-heading"><span>UNIT PROFILE</span><strong>${c.name}</strong><small>${c.wounds}/3 W · ${c.crew} crew</small></div><p>War machine · T6 · Cannonball R60″ S10 AP −3 · Grapeshot R12″ S4 AP −1</p>`;}
 else profile.innerHTML='<div class="ledger-heading"><span>UNIT PROFILE</span><strong>No unit selected</strong></div><table><thead><tr><th>Model</th><th>M</th><th>WS</th><th>BS</th><th>S</th><th>T</th><th>W</th><th>I</th><th>A</th><th>Ld</th></tr></thead><tbody><tr><th>—</th><td colspan="9">—</td></tr></tbody></table>';
 if(state.format.id==='battle-march'){renderBmScore();return;}
 const scores=P.scoreRows(state,G);$('scoreboard').innerHTML='<div class="ledger-heading"><span>BATTLE SCORE</span><strong>Round '+state.round+'</strong></div>'+scores.map(row=>`<div class="score-row ${row.team}"><b><i class="score-dot"></i>${row.name}</b><span>${row.units} units · ${row.models} models</span><span>${row.engaged} engaged</span><strong class="${lastVp&&row.vp>lastVp[row.team]?'vp-pop':''}">${row.vp} VP</strong></div>`).join('');lastVp=Object.fromEntries(scores.map(row=>[row.team,row.vp]));
}
function renderLabels(){const root=$('boardLabels');root.replaceChildren();for(const u of state.units.filter(v=>v.x!==null)){const box=G.rectangle(u),label=document.createElement('div');label.className='unit-label'+(u.fleeing?' fleeing':'')+(u.moved?' finished':'');label.style.left=(u.x/state.board.width*100)+'%';label.style.top=(Math.min(state.board.height-.5,box.bottom+.5)/state.board.height*100)+'%';label.innerHTML=`<b>${P.shortName(u)}</b><small>${u.fleeing?'FLEEING':u.engaged?'ENGAGED':u.moved?'FINISHED':''}</small>${G.activeSpells(u).map(sp=>`<small class="spell-tag" title="${sp.name}">${sp.short.toUpperCase()}</small>`).join('')}${effectList(u).length?`<em class="effect-badge">${effectList(u).join(' · ')}</em>`:''}`;root.append(label);}for(const c of state.cannons.filter(c=>c.x!==null)){const label=document.createElement('div');label.className='unit-label cannon-label'+(c.shot?' finished':'');label.style.left=(c.x/state.board.width*100)+'%';label.style.top=((c.y+2.3)/state.board.height*100)+'%';label.innerHTML=c.name+misfireTag(c);root.append(label);}
 // The Deathshrieker carries a label only while a misfire keeps it from shooting.
 const r=state.rocket;if(r.x!==null&&misfireStatus(r)){const label=document.createElement('div');label.className='unit-label cannon-label';label.style.left=(r.x/state.board.width*100)+'%';label.style.top=((r.y+2.3)/state.board.height*100)+'%';label.innerHTML='Deathshrieker'+misfireTag(r);root.append(label);}}
// A Black Powder malfunction stops a war machine shooting in its next turn; shown like fleeing.
function misfireStatus(m){if(!m||m.x===null||!(m.disabledUntil>=state.round)||!m.disabledUntil)return null;if(state.round===m.disabledUntil){if(state.team===m.team&&state.stage!=='deployment')return 'MISFIRE · CANNOT SHOOT THIS TURN';if(m.team===state.firstPlayer)return null;}return 'MISFIRE · CANNOT SHOOT NEXT TURN';}
function misfireTag(m){const status=misfireStatus(m);return status?`<small class="misfire-tag" title="Black Powder Misfire: it cannot shoot in round ${m.disabledUntil}.">${status}</small>`:'';}
function animateUnit(id,from,charge=false){const u=G.getUnit(state,id),block=$('unitsLayer').querySelector(`[data-unit="${id}"] > g[transform]`);if(!block||!from||u.x===null||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const span=Math.hypot(u.x-from.x,u.y-from.y),turn=P.shortestTurn(from.heading,G.heading(u)),duration=charge?Math.max(700,span*90):Math.max(500,span*220),start=performance.now();movementAnimating=true;function frame(now){const t=Math.min(1,(now-start)/duration),e=charge?t*t:0.5-0.5*Math.cos(Math.PI*t),x=from.x+(u.x-from.x)*e,y=from.y+(u.y-from.y)*e,h=from.heading+turn*e;block.setAttribute('transform',`translate(${x*S} ${y*S}) rotate(${h})`);if(t<1)requestAnimationFrame(frame);else movementAnimating=false;}requestAnimationFrame(frame);}
function renderDestruction(){const layer=$('boardEffects');for(const u of state.units){const old=lastUnitPositions.get(u.id);if(old&&u.destroyed&&u.x===null){const burst=document.createElement('div');burst.className='death-effect';burst.style.left=(old.x/state.board.width*100)+'%';burst.style.top=(old.y/state.board.height*100)+'%';burst.innerHTML=`<i></i><b>DESTROYED</b><small>+${state.format.id==='battle-march'?(u.cost??0):100} VP</small>`;layer.append(burst);setTimeout(()=>burst.remove(),1100);}if(u.x===null)lastUnitPositions.delete(u.id);else lastUnitPositions.set(u.id,{x:u.x,y:u.y});}}
function impactEffect(point,kind,slain=0){if(!point||!Number.isFinite(point.x)||!Number.isFinite(point.y)||point.x<0||point.x>state.board.width||point.y<0||point.y>state.board.height)return;const burst=document.createElement('div');burst.className='shot-impact '+kind;burst.style.left=(point.x/state.board.width*100)+'%';burst.style.top=(point.y/state.board.height*100)+'%';burst.setAttribute('aria-hidden','true');burst.innerHTML='<i class="impact-flash"></i><i class="impact-ring"></i><i class="impact-spark spark-one"></i><i class="impact-spark spark-two"></i><i class="impact-spark spark-three"></i>'+(slain?`<b>−${slain}</b>`:'');$('boardEffects').append(burst);setTimeout(()=>burst.remove(),950);}
function artilleryImpact(report,positions){if(report.misfire)return;const point=report.impact??report.strike??positions.get(report.target);impactEffect(point,'artillery',report.unsaved);const hitUnits=new Set((report.affected??[]).map(hit=>hit.unit));for(const id of hitUnits){const unit=positions.get(id);if(unit&&(!point||Math.hypot(unit.x-point.x,unit.y-point.y)>2))impactEffect(unit,'artillery');}}
function positionDice(label,count){const unit=state.units.find(u=>u.x!==null&&(label.includes(u.id)||label.includes(P.shortName(u))))??state.cannons.find(c=>label.includes(c.id)||label.includes(c.name))??(label.includes('Deathshrieker')?state.rocket:G.getUnit(state));const panel=$('diceAnimation');if(unit?.x===null||unit?.x===undefined){panel.style.left='50%';panel.style.top='45%';panel.style.transform='translate(-50%,-50%)';}else{const right=unit.x<state.board.width/2;panel.style.left=((unit.x/state.board.width*100)+(right?3:-3))+'%';panel.style.top=(unit.y/state.board.height*100)+'%';panel.style.transform=right?'translate(0,-50%)':'translate(-100%,-50%)';}panel.style.setProperty('--dice-size',count<=4?'52px':count<=10?'40px':'30px');panel.style.borderColor='var(--army-primary)';}
const armyName=team=>G.armyName(team,state);
function svg(tag,attrs,parent,text){const e=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));if(text!==undefined)e.textContent=text;parent.append(e);return e;}
