// ---- Terrain ----
// Each feature drawn on its footprint: hills with a contour and their top, woods with trees, low and
// high walls as lines, buildings and rocks as blocks. Hover for what it does.
const TERRAIN_MOVE={open:'open ground',difficult:'difficult terrain (Movement −1, the lower charge die)',dangerous:'dangerous terrain (difficult, and a Dangerous Terrain test for each model)',impassable:'impassable'};
