$('cannonFireButton').onclick=async()=>{if(rolling)return;try{const id=cannonSelected,c=state.cannons.find(c=>c.id===id),target=cannonTarget,fireMode=cannonMode,dice=G.rollCannonDice(),positions=new Map(state.units.filter(u=>u.x!==null).map(u=>[u.id,{x:u.x,y:u.y}]));await animateCannonDice(fireMode==='ball'?[dice.strike,dice.bounce]:[dice.strike],c.name);const report=G.fireCannon(state,id,target,fireMode,dice,Math.random,{aimShort:cannonAimShort});if(report.misfire)await animatedRoll(1,c.name+' · Misfire',[report.misfire]);cannonSelected=null;advanceSelection(id);render();artilleryImpact(report,positions);notify(report.misfire?`${c.name} misfire ${report.misfire}: ${report.misfire===1?'destroyed':report.misfire<=4?'malfunction':'shot lost'}.`:`${c.name} ${fireMode==='ball'?'cannonball':'grapeshot'}: ${report.hits} hits, ${report.unsaved} slain${report.bounce==='misfire'?'; bounce stopped on a misfire':''}.`);}catch(e){notify(e.message,true);}};
