$('rocketDemolition').onclick=()=>{rocketProfile='demolition';render();};$('rocketIncendiary').onclick=()=>{rocketProfile='incendiary';render();};$('rocketIndirect').onchange=e=>{rocketIndirect=e.target.checked;render();};
