// Daemonsmith: once per turn, when it is in range, the player may re-roll one of the rocket dice
// after seeing them. Click the die to re-roll, or keep the roll.
function chooseEngineerDie(){
 return new Promise(resolve=>{
  const panel=$('diceAnimation'),[a,b]=$('animatedDice').querySelectorAll('.animated-die'),keep=document.createElement('button');clearTimeout(diceHideTimer);panel.hidden=false;panel.classList.add('choosing');rolling=true;
  const done=which=>{panel.classList.remove('choosing');for(const d of [a,b]){d.onclick=null;d.onkeydown=null;d.removeAttribute('role');d.removeAttribute('tabindex');d.removeAttribute('title');}keep.remove();$('diceAnimationResult').textContent=$('diceAnimationResult').textContent.replace(/ · Daemonsmith.*$/,'');rolling=false;resolve(which);};
  for(const [d,which,name] of [[a,'artillery','Artillery'],[b,'scatter','Scatter']]){d.setAttribute('role','button');d.tabIndex=0;d.title=`Daemonsmith: re-roll the ${name} die`;d.onclick=()=>done(which);d.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();done(which);}};}
  $('diceAnimationResult').textContent+=' · Daemonsmith: click a die to re-roll it';
  keep.className='quiet keep-roll';keep.textContent='Keep this roll';keep.onclick=()=>done(null);panel.append(keep);keep.focus();
 });
}
async function animateRocketDice(dice){if(rolling)return;rolling=true;clearTimeout(diceHideTimer);const panel=$('diceAnimation'),tray=$('animatedDice'),faces=['2','4','6','8','10','✹'],arrows=['↑','↗','→','↘','↓','↙','←','↖'];positionDice('Deathshrieker',2);panel.hidden=false;panel.classList.add('rolling');$('diceAnimationLabel').textContent='Deathshrieker · Artillery + Scatter';$('diceAnimationResult').textContent='Rolling…';tray.replaceChildren();const a=document.createElement('span'),b=document.createElement('span');a.className=b.className='animated-die';tray.append(a,b);const timer=setInterval(()=>{a.textContent=faces[Math.floor(Math.random()*6)];b.textContent=Math.random()<1/3?'HIT':arrows[Math.floor(Math.random()*8)];},65);await new Promise(resolve=>setTimeout(resolve,matchMedia('(prefers-reduced-motion: reduce)').matches?50:550));clearInterval(timer);a.textContent=dice.artillery==='misfire'?'MISFIRE':String(dice.artillery);b.textContent=dice.scatter==='hit'?'HIT':arrows[Math.round(dice.scatter/45)%8];panel.classList.remove('rolling');$('diceAnimationResult').textContent=`Artillery ${a.textContent} · Scatter ${b.textContent}`;rolling=false;diceHideTimer=setTimeout(()=>{panel.hidden=true;},1600);}
$('rocketFireButton').onclick=async()=>{if(rolling)return;try{const target=rocketTarget,profile=rocketProfile,indirect=rocketIndirect;let dice=G.rollRocketDice();const positions=new Map(state.units.filter(u=>u.x!==null).map(u=>[u.id,{x:u.x,y:u.y}]));await animateRocketDice(dice);if(G.canEngineerReroll(state)){const which=await chooseEngineerDie();if(which){dice=G.engineerReroll(state,dice,which);await animateRocketDice(dice);}}const report=G.fireRocket(state,target,profile,dice,Math.random,{indirect});if(report.misfire){await animatedRoll(1,'Black Powder Misfire',[report.misfire]);showDice([report.misfire],'Deathshrieker misfire');}else{$('boardRoll').textContent=`Artillery ${dice.artillery} · Scatter ${dice.scatter==='hit'?'HIT':dice.scatter+'°'} · ${(report.units??[]).reduce((n,u)=>n+u.killed,0)} killed`;}rocketSelected=false;advanceSelection('A5');render();artilleryImpact(report,positions);notify(report.misfire?`Deathshrieker misfire ${report.misfire}: ${report.misfire===1?'destroyed':report.misfire<=4?'malfunction':'Pffft; shot lost'}.`:`${G.ROCKET_PROFILES[profile].name}: ${report.scatter==='hit'?'direct hit':report.scatterDistance+'″ scatter'}, ${report.hits} hit${report.hits===1?'':'s'}.${P.rocketCasualties(report)}`);}catch(e){notify(e.message,true);}};

function renderMovementBar(u){
 const total=G.moveAllowance(u,{mode:u.movementMode??mode,medium:u.movementMedium??medium,difficult:!!u.difficultThisMove}),remaining=G.movementRemaining(u,u.movementMode??mode,u.movementMedium??medium),spent=total-remaining;
 const step=state.stage==='movement'&&state.movementStep==='remaining'&&G.canAct(state,u)?G.planMove(u,currentOrder()).cost:0;
 const preview=Math.min(remaining,step);const bar=$('movementInches');bar.replaceChildren();
 bar.setAttribute('aria-label',fmt(remaining)+' of '+total+' inches remaining');bar.setAttribute('aria-valuemax',total);bar.setAttribute('aria-valuenow',remaining);
 for(let i=0;i<total;i++){
 const cell=document.createElement('span');cell.className='inch-cell';cell.title='Movement inch '+(i+1);
 const available=Math.max(0,Math.min(1,total-i-spent)),after=Math.max(0,Math.min(1,total-i-spent-preview));
 cell.style.setProperty('--available',(available*100)+'%');cell.style.setProperty('--after',(after*100)+'%');cell.textContent=(i+1)+'″';bar.append(cell);
 }
 $('movementInchesLabel').textContent=fmt(remaining)+'″ remaining / '+total+'″';
 $('movementInchesKey').textContent=u.engaged?'Engaged — no movement':u.moved?'Movement finished':step>0?'Green: left after preview · gold: planned step · gray: spent':'Each square = 1″ · partial squares show fractions';
}

function positionOrders(){/* Orders are anchored in the fixed command column. */}
const ordersHandle=$('ordersDragHandle');
ordersHandle.addEventListener('pointerdown',e=>{if(e.button!==0||!ordersOpen)return;const r=$('unitOrders').getBoundingClientRect();ordersDrag={id:e.pointerId,dx:e.clientX-r.left,dy:e.clientY-r.top};ordersHandle.setPointerCapture(e.pointerId);e.preventDefault();});
ordersHandle.addEventListener('pointermove',e=>{if(ordersDrag?.id!==e.pointerId)return;manualOrders={x:e.clientX-ordersDrag.dx,y:e.clientY-ordersDrag.dy};positionOrders();});
for(const event of ['pointerup','pointercancel'])ordersHandle.addEventListener(event,e=>{if(ordersDrag?.id!==e.pointerId)return;ordersDrag=null;if(ordersHandle.hasPointerCapture(e.pointerId))ordersHandle.releasePointerCapture(e.pointerId);});
ordersHandle.addEventListener('keydown',e=>{const change={ArrowLeft:[-24,0],ArrowRight:[24,0],ArrowUp:[0,-24],ArrowDown:[0,24]}[e.key];if(!change||!ordersOpen)return;e.preventDefault();const r=$('unitOrders').getBoundingClientRect();manualOrders={x:(manualOrders?.x??r.left)+change[0],y:(manualOrders?.y??r.top)+change[1]};positionOrders();});
function closeOrders(){ordersOpen=false;$('unitOrders').hidden=true;hideUnitTooltip();render();}
function refreshPreview(){clampInputs();hideUnitTooltip();draw();renderOrders();}
function placeSelected(x,y){return safely(()=>{const id=state.selected;if(botOwns(id))throw Error('The bot deploys its own army.');G.place(state,id,x,y);deployFocus=id;notify(`${pieceName(id)} placed: drag it, nudge it or turn it, then Confirm.`);ordersOpen=false;});}
function showDice(dice,label){const total=dice.reduce((a,b)=>a+b,0);rolls.unshift({dice,total,label});rolls=rolls.slice(0,8);$('diceResults').replaceChildren();dice.forEach(d=>{const span=document.createElement('span');span.className='die';span.textContent=['','⚀','⚁','⚂','⚃','⚄','⚅'][d];span.setAttribute('aria-label',String(d));$('diceResults').append(span);});$('diceSummary').textContent=`${total} total · ${label}`;$('boardRoll').textContent=`${dice.join(' + ')} = ${total}`;$('rollHistory').replaceChildren();rolls.forEach(r=>{const li=document.createElement('li');li.textContent=`${r.label}: ${r.dice.join(' + ')} = ${r.total}`;$('rollHistory').append(li);});}
function skipEmptySteps(){return G.skipEmptySteps(state);}
function scheduleAi(){if(aiMode!=='ai'||aiTimer||rolling||autoResolving||movementAnimating||!AI.shouldAct(state))return;aiTimer=setTimeout(runAiStep,650);}
function runAiStep(){aiTimer=null;if(aiMode!=='ai'||!AI.shouldAct(state))return;if($('rulesDialog').open||$('resetDialog').open||rolling||autoResolving||movementAnimating){aiTimer=setTimeout(runAiStep,650);return;}try{const prior=humanSide(state.team)?selectedActorId():null,before=new Map(state.units.filter(u=>u.x!==null).map(u=>[u.id,{x:u.x,y:u.y,heading:G.heading(u),charging:u.charge?.status==='declared'}]));const out=AI.takeStep(state),decision=AI.humanDecision(state);ordersOpen=!!decision;rocketSelected=false;cannonSelected=null;if(decision)state.selected=decision.id;else if(prior&&humanSide(state.team)&&!state.pendingCombat){const again=actors().find(a=>a.id===prior);if(again)selectActor(again);else advanceSelection(prior);}try{render();for(const [id,from]of before){const u=G.getUnit(state,id);if(u&&u.x!==null&&(Math.hypot(u.x-from.x,u.y-from.y)>.01||Math.abs(G.heading(u)-from.heading)>.1))animateUnit(id,from,from.charging);}if(out.spell&&out.report)spellCard(out.report,out.point);if(out.artillery)artilleryImpact(out.report,out.positions);else if(out.spell&&out.report?.effect?.unsaved)impactEffect(out.point,'volley',out.report.effect.unsaved);else if(out.report?.hits)impactEffect(out.point,'volley',out.report.unsaved);if(out.roll)animatedRoll(2,out.roll.label,out.roll.dice,{color:P.themeForTeam(state,out.roll.team).primary}).catch(()=>{});}catch(effect){console.error('Bot step effects failed',effect);}notify(raidNews()+reserveNews()+vortexNews()+flightNews()+(decision?(out.spell?out.message+' ':'')+decision.message:out.message));}catch(e){aiMode='human';render();notify('The bot stopped: '+e.message+'. Continue in two-player mode.',true);}finally{continueCombat();scheduleAi();}}
// Watchdog: the bot is otherwise rescheduled only when the page redraws, so a redraw that happens
// during an animation or roll could leave it idle. Check regularly and restart it when due.
setInterval(()=>{if(aiMode==='ai'&&!aiTimer)scheduleAi();},1000);
function nextPhase(){safely(()=>{const before=state.stage,previous=state.selected;ordersOpen=false;rocketSelected=false;cannonSelected=null;if(state.stage==='deployment'){if(state.deployOrder?.alternate&&bmDeployStep())return;if(!state.deployOrder?.alternate&&aiMode==='ai'&&AI.readyToDeploy(state)){deployDone=true;botDeploy();return;}G.begin(state);}else if(state.stage==='movement'&&state.movementStep==='declare')G.finishDeclarations(state);else G.nextPhase(state);if(before!=='movement'||state.movementStep!=='declare')declinedCharges.clear();const skipped=skipEmptySteps();advanceSelection(previous);resetOrder();notify(raidNews()+reserveNews()+vortexNews()+flightNews()+`${skipped.length?skipped.join(', ')+' skipped: no eligible actions. ':''}${armyName(state.team)} · ${state.stage==='movement'?movementStepName():title(state.stage)}. ${state.stage==='combat'?'Select engaged regiments to fight.':state.stage==='movement'?'Choose a regiment for orders.':'Choose a unit to act.'}`);});}
$('nextButton').onclick=nextPhase;$('topNextPhase').onclick=nextPhase;
