// ---- Scouts, Vanguard and Ambushers in the unit's orders ----
// A unit with Ambushers may be held in reserve until it is deployed; a unit with Vanguard may
// make (or decline) its Vanguard move when its army's turn to move one comes.
function renderSpecialDeploy(u){
 let box=$('specialDeploy');if(!box){$('deployControls').insertAdjacentHTML('afterend','<div id="specialDeploy" class="special-deploy"></div>');box=$('specialDeploy');}
 box.replaceChildren();box.hidden=state.stage!=='deployment'||!u||!humanSide(u.team);if(box.hidden)return;
 const add=(label,run,primary=false)=>{const b=document.createElement('button');b.className=(primary?'primary':'quiet')+' wide';b.textContent=label;b.onclick=()=>safely(run);box.append(b);};
 const note=text=>{const p=document.createElement('p');p.className='control-help';p.textContent=text;box.append(p);};
 if(G.unitHasRule(u,'ambushers')&&!u.deployed){if(G.inReserve(u)){note('Held in reserve (Ambushers): from round 2 it arrives on a 4+ at your Start of Turn, against a battlefield edge you choose.');add('Deploy it on the battlefield instead',()=>{G.holdInReserve(state,u.id,false);notify(`${P.shortName(u)} will be deployed.`);});}else add('Hold in reserve (Ambushers)',()=>{G.holdInReserve(state,u.id,true);notify(`${P.shortName(u)} is held in reserve.`);});}
 if(G.unitHasRule(u,'scouts')&&!u.deployed)note('Scouts: deploys after every other unit of both armies, in its zone or more than 12″ from every enemy model. Placed outside its zone, it cannot charge in its first turn.');
 const v=G.vanguardPending(state)?G.vanguardState(state):null;
 if(v&&G.vanguardUnits(state,v.next).some(w=>w.id===u.id)&&!(v.both&&!v.rollOff)){if(v.active===u.id)note('Vanguard move: an ordinary move (it may manoeuvre, not march). Finish it from the main button.');else if(!v.active){add('Make a Vanguard move',()=>{G.beginVanguard(state,u.id);ordersOpen=true;resetOrder();notify(`${P.shortName(u)} makes its Vanguard move: move it, then finish.`);},true);add('No Vanguard move',()=>{G.endVanguard(state,u.id,false);notify(`${P.shortName(u)} stays where it was deployed.`);});}}
}
