// ---- Saving and resuming ----
// The battle in play is saved in this browser after every change. The one left unfinished on the
// last visit is kept apart, so it can still be resumed after a new battle starts; any battle can be
// downloaded as a file and loaded again.
const SAVE_KEY='project-tow-autosave',PREVIOUS_KEY='project-tow-previous';
const store={get:k=>{try{return localStorage.getItem(k);}catch{return null;}},set:(k,v)=>{try{localStorage.setItem(k,v);return true;}catch{return false;}},drop:k=>{try{localStorage.removeItem(k);}catch{}}};
let autosaveTimer=null;
function autosave(){if(autosaveTimer)return;autosaveTimer=setTimeout(()=>{autosaveTimer=null;try{store.set(SAVE_KEY,G.saveGame(state,{aiMode}));}catch{}},400);}
// One line naming a saved battle: its format, round, whose turn and phase, and when it was saved.
function saveLabel(summary,saved){const when=saved?new Date(saved).toLocaleString([], {day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'';const turn=summary.finished?'finished':summary.stage==='deployment'?'deployment':`round ${summary.round} · ${armyName(summary.team)} · ${title(summary.stage)}`;return `${summary.format}${summary.points?' · '+summary.points+' pts':''} · ${turn}${when?' · saved '+when:''}`;}
function readSave(text){try{return G.loadGame(text);}catch{return null;}}
// The battle left on the last visit, if it was worth keeping (started and unfinished).
const previousSave=(()=>{const last=store.get(SAVE_KEY),saved=last&&readSave(last);if(saved&&!saved.summary.finished&&(saved.state.stage!=='deployment'||saved.state.units.some(u=>u.x!==null))){store.set(PREVIOUS_KEY,last);return saved;}const kept=store.get(PREVIOUS_KEY),old=kept&&readSave(kept);return old&&!old.summary.finished?old:null;})();
// Put a loaded battle in play, with the app's own choices reset as for a new game.
function resumeBattle(out,message){$('diceAnimation').hidden=true;chargeTarget=null;shootTarget=null;rocketTarget=null;rocketSelected=false;cannonSelected=null;cannonTarget=null;cannonMode='ball';cannonAimShort=6;rocketProfile='demolition';rocketIndirect=false;manualOrders=null;autoPlace=false;deployDone=state.stage!=='deployment';deployFocus=null;resultShown=false;seenRaids=null;templateAim=null;templatePick=null;spellShape=null;clearTimeout(deployTimer);deployTimer=null;clearTimeout(aiTimer);aiTimer=null;if($('resultDialog').open)$('resultDialog').close();
 state=out.state;if(['ai','human'].includes(out.extra?.aiMode))aiMode=out.extra.aiMode;deployDone=state.stage!=='deployment';rolls=[];ordersOpen=false;resetOrder();$('diceResults').innerHTML='<span class="empty-die">?</span><span class="empty-die">?</span>';$('diceSummary').textContent='';$('boardRoll').textContent='';$('rollHistory').innerHTML='<li>No rolls yet.</li>';
 if(state.format?.id==='battle-march')$('formatSelect').value='battle-march';else $('formatSelect').value='classic';$('opponentSelect').value=state.units.find(u=>u.team==='iron')?.faction??'empire';render();notify(message);}
function renderSaveDialog(){const box=$('saveResume');box.replaceChildren();$('saveError').hidden=true;if(previousSave){const b=document.createElement('button');b.className='primary wide';b.textContent='Resume your last battle';const note=document.createElement('small');note.textContent=saveLabel(previousSave.summary,previousSave.saved);b.onclick=()=>{$('saveDialog').close();resumeBattle(structuredClone(previousSave),`Resumed: ${saveLabel(previousSave.summary,previousSave.saved)}.`);};box.append(b,note);}}
$('saveButton').onclick=()=>{renderSaveDialog();$('saveDialog').showModal();};
$('saveClose').onclick=()=>$('saveDialog').close();
$('saveDownload').onclick=()=>{const text=G.saveGame(state,{aiMode}),url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`project-tow-${(state.format?.id??'classic')}-round-${state.round}-${new Date().toISOString().slice(0,16).replace(/[:T]/g,'-')}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Battle downloaded. Load it again from Save / Load.');};
