async function react(choice){if(rolling)return;try{const id=choice==='stand-shoot'?$('reactionControls').dataset.charger:$('reactionControls').dataset.pending,charger=G.getUnit(state,id),point=charger&&{x:charger.x,y:charger.y},result=G.chargeReaction(state,id,choice);if(result.report)await animateVolley(result.report,result.defender+' · Stand & Shoot');if(result.fleeDice){await animatedRoll(2,result.defender+' · Flee',result.fleeDice);showDice(result.fleeDice,result.defender+' flees '+result.fleeDistance+'″');}if(!openDecision())advanceSelection(result.charger);render();if(result.report?.hits)impactEffect(point,'volley',result.report.unsaved);notify(choice==='hold'?result.defender+' Holds.':choice==='flee'?`${result.defender} Flees ${result.fleeDistance}″ directly away${result.fledOffBoard?' and leaves the battlefield':''}.${P.fleeSummary(result.flee)}`:`${result.defender} Stands & Shoots: ${result.report.unsaved} slain${result.stopped?' — charge stopped.':''}.`);}catch(e){notify(e.message,true);}}
$('reactionHold').onclick=()=>react('hold');$('reactionStand').onclick=()=>react('stand-shoot');$('reactionFlee').onclick=()=>react('flee');
function drawCharge(u,layer){
 const id=u.charge?.target??chargeTarget,t=G.getUnit(state,id);if(!t||t.x===null)return;const p=G.chargePlan(state,u,t);
 svg('path',{d:'M'+u.x*S+' '+u.y*S+'L'+t.x*S+' '+t.y*S,class:'charge-line'},layer);
 const group=$('unitsLayer').querySelector('[data-unit="'+t.id+'"]')??$('board').querySelector('[data-rocket="'+t.id+'"],[data-cannon="'+t.id+'"]');group?.classList.add('charge-target');
 if(p.end&&!p.error){if(Math.abs(p.alignAngle)>1)drawUnit(p.contact,layer,true);drawUnit(p.end,layer,true);svg('text',{x:(u.x+t.x)*S/2,y:(u.y+t.y)*S/2-12,'text-anchor':'middle',class:'measure-label'},layer,fmt(p.cost)+'″ · '+p.face+' · '+Math.round(p.angle)+'° wheel + '+Math.round(p.alignAngle)+'° free align');}
}
function renderChargeControls(u){
 const show=state.stage==='movement'&&state.movementStep!=='remaining'&&u.team===state.team;
 $('chargeControls').hidden=!show;if(!show)return;
 $('chargeStep').textContent=movementStepName();const declared=u.charge?.status==='declared',available=G.canAct(state,u),resolving=state.movementStep==='charges';
 $('chargeHelp').textContent=u.engaged?'This regiment is engaged.':declared?'Target '+u.charge.target+' · reaction '+u.charge.reaction+'.':resolving?'This regiment has no declared charge. Select a charger on the board.':'Click an enemy on the board, or choose below. One measured approach wheel and one free alignment wheel.';
 const impetuous=G.isImpetuous(state,u)&&!resolving&&!declared&&available&&G.availableCharges(state,u).length>0;$('impetuousButton').hidden=!impetuous||u.impetuousTest!==null;if(impetuous&&u.impetuousTest===false)$('chargeHelp').textContent='Impetuous failed: this unit must declare a charge.';else if(impetuous&&u.impetuousTest===null)$('chargeHelp').textContent=`${u.faction==='orc'?'This Orc Mob':'This unit (Impetuous near a Phantasmagoria)'} can charge. Test Impetuous first; on failure it must charge.`;
 $('chargeTargets').replaceChildren();
 if(!declared&&!resolving&&available)for(const t of G.combatants(state).filter(v=>v.team!==u.team&&(v.role!=='warmachine'||v.x!==null))){
  // Several units may charge one enemy, and a unit already in combat can be charged.
  const p=G.chargePlan(state,u,t),joining=state.units.filter(v=>v.id!==u.id&&v.charge?.status==='declared'&&v.charge.target===t.id),b=document.createElement('button');b.className='charge-choice';b.dataset.chargeTarget=t.id;b.setAttribute('aria-pressed',String(chargeTarget===t.id));b.textContent=P.unitName(t)+' · '+(p.error??(fmt(p.cost)+'″ · '+p.face+(t.engaged?' · already in combat':'')+(joining.length?' · also charged by '+joining.map(v=>P.shortName(v)).join(', '):'')));b.disabled=!!p.error;b.onclick=()=>{chargeTarget=t.id;render();};$('chargeTargets').append(b);
 }
 foldUnavailable($('chargeTargets'));
 const t=G.getUnit(state,u.charge?.target??chargeTarget),p=t?G.chargePlan(state,u,t):null;
 $('chargePreview').textContent=declared?'Declared against '+u.charge.target+' · reaction: '+(u.charge.reaction==='pending'?'chosen once every charge is declared':u.charge.reaction):p?(p.error??('Need '+fmt(p.cost)+'″ · range = '+G.profile(u).M+' + highest D6')):'Maximum charge range: '+(G.profile(u).M+6)+'″.';
 $('declareCharge').hidden=resolving||declared||state.movementStep==='reactions';$('declareCharge').disabled=!available||!p||!!p.error||(impetuous&&u.impetuousTest===null);
 $('noCharge').hidden=true;$('noCharge').disabled=!available||(impetuous&&u.impetuousTest===false);
 $('cancelCharge').hidden=!declared||resolving||u.charge.reaction!=='pending';$('resolveCharge').hidden=!declared||!resolving;
 $('finishDeclarations').hidden=true;$('finishDeclarations').disabled=state.units.some(v=>v.charge?.reaction==='pending');
}
$('declareCharge').onclick=()=>safely(()=>{const attacker=state.selected,target=chargeTarget,out=G.declareCharge(state,attacker,target);notify(`${attacker} declares a charge on ${target}${out.reaction==='pending'?'. It reacts once every charge has been declared.':' (it can only Hold).'}`);chargeTarget=null;advanceSelection(attacker);});
$('noCharge').onclick=()=>{const id=state.selected;declinedCharges.add(id);advanceSelection(id);render();notify(P.unitName(G.getUnit(state,id))+' does not charge.');};
$('impetuousButton').onclick=async()=>{if(rolling)return;const id=state.selected;try{const dice=await animatedRoll(2,id+' · Impetuous test');safely(()=>{const passed=G.impetuousTest(state,id,dice);showDice(dice,id+' Impetuous');notify(passed?id+' holds discipline; charging is optional.':id+' fails Impetuous and must declare a charge.');});}catch(e){notify(e.message,true);}};
$('cancelCharge').onclick=()=>safely(()=>G.cancelCharge(state,state.selected));
$('finishDeclarations').onclick=nextPhase;
$('resolveCharge').onclick=async()=>{
 if(rolling)return;const id=state.selected;
 try{const unit=G.getUnit(state,id),from={x:unit.x,y:unit.y,heading:G.heading(unit)},first=await animatedRoll(2,id+' · Charge roll · keep highest'),plan=G.chargePlan(state,unit,G.getUnit(state,unit.charge.target)),m=G.profile(unit).M,rerolled=G.hasWarband(unit)&&!plan.error&&m+Math.max(...first)<plan.cost,dice=rerolled?await animatedRoll(2,id+' · Warband charge reroll'):first;if(safely(()=>{const fleeing=unit.charge.reaction==='flee',r=G.resolveCharge(state,id,dice),mv=r.range-r.roll-(r.swift??0),sum=mv+(r.swift?' + '+r.swift:'')+' + '+r.roll,label=id+' charge: '+(r.success?'SUCCESS':r.pursuit?'PURSUIT':'FAILED');showDice(dice,label);$('diceSummary').textContent=(rerolled?'Warband reroll · ':'')+'Kept '+r.roll+(r.difficult?' (the lower die: difficult ground)':'')+' + M'+mv+(r.swift?' + '+r.swift+' Swiftstride':'')+' = '+r.range+'″ · '+label;document.querySelectorAll('#animatedDice .animated-die').forEach((el,i)=>el.classList.toggle('kept',dice[i]===r.roll));$('diceAnimationResult').textContent=sum+' = '+r.range+'″ · '+(r.success?'CHARGE!':r.pursuit?'Pursuit move':'Failed charge');$('boardRoll').textContent=dice.join(', ')+' → '+r.range+'″ charge';const outcome=r.runDown?'Fleeing unit run down.':r.success?'Charge successful — engaged!':fleeing?(r.targetLeftBoard?'Fleeing unit left the battlefield and was destroyed; ':'Fleeing unit escaped; ')+'charger moved '+fmt(r.distance)+'″.':'Failed charge; moved '+fmt(r.distance)+'″.';notify(id+' → '+r.target+': '+sum+' = '+r.range+'″. '+(r.difficult?'Through difficult ground: the lower die counts and Movement −1. ':'')+(rerolled?'Warband reroll. ':'')+outcome+(unit.charge?.disordered?' A disordered charge ('+unit.charge.disordered+'): no Initiative bonus for charging.':'')+((n=>n?' '+n.trim():'')(crossingNews(r.vortexHits)+terrainNews(r.terrainHits)))+(state.movementStep==='remaining'?' Remaining Moves.':'')+(G.reformOffer(state,id)?' It may attempt to reform (Leadership test): choose its facing.':''));if(G.reformOffer(state,id)){state.selected=id;ordersOpen=true;}else advanceSelection(id);}))animateUnit(id,from,true);}catch(e){notify(e.message,true);}
};
const faces=['','⚀','⚁','⚂','⚃','⚄','⚅'];
async function animatedRoll(count,label,preset=null,{color=null}={}){
 if(rolling)throw Error('Wait for the current roll to finish.');clearTimeout(diceHideTimer);const dice=preset??G.rollD6(count);rolling=true;
 const panel=$('diceAnimation'),tray=$('animatedDice');positionDice(label,dice.length);if(color)panel.style.borderColor=color;panel.hidden=false;panel.classList.add('rolling');$('diceAnimationLabel').textContent=label;$('diceAnimationResult').textContent='Rolling…';tray.replaceChildren();
 const pieces=dice.map((d,i)=>{const el=document.createElement('span');el.className='animated-die';el.style.setProperty('--delay',(i%5)*-80+'ms');el.textContent=faces[(i%6)+1];el.setAttribute('aria-hidden','true');tray.append(el);return el;});
 const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;let frame=0;
 const timer=reduce?null:setInterval(()=>pieces.forEach((e,i)=>e.textContent=faces[(++frame+i)%6+1]),65);
 await new Promise(resolve=>setTimeout(resolve,reduce?50:550));if(timer)clearInterval(timer);
 pieces.forEach((e,i)=>{e.textContent=faces[dice[i]];e.setAttribute('aria-label',String(dice[i]));e.removeAttribute('aria-hidden');});
 panel.classList.remove('rolling');$('diceAnimationResult').textContent=dice.join(' + ')+' = '+dice.reduce((x,y)=>x+y,0);rolling=false;diceHideTimer=setTimeout(()=>{panel.hidden=true;},1600);
 // A combat that paused for this roll (a bot's dispel of an Assailment, say) carries on after it.
 setTimeout(continueCombat,0);
 return dice;
}
async function freeRoll(count){if(rolling)return;try{const dice=await animatedRoll(count,'Dice roller');showDice(dice,'Free roll');}catch(e){notify(e.message,true);}}
// Input waits while dice roll or units move; only the Daemonsmith's re-roll choice stays clickable.
for(const event of ['click','pointerdown','keydown'])document.addEventListener(event,e=>{if((rolling||autoResolving||movementAnimating)&&!e.target.closest?.('.dice-animation.choosing')){e.preventDefault();e.stopImmediatePropagation();}},true);
for(const event of ['click','pointerdown','keydown'])document.addEventListener(event,e=>{if(aiMode!=='ai'||state.team!=='iron'||state.stage==='deployment'||state.stage==='finished'||AI.humanDecision(state))return;if(e.target.closest('#aiMode,#resetButton,#rulesButton,#closeRules,#resetDialog,#rulesDialog,#endBattle,#endDialog,#resultDialog,#scoreboard,#saveButton,#saveDialog'))return;e.preventDefault();e.stopImmediatePropagation();},true);

render();
// A battle left unfinished on the last visit is offered at once.
if(previousSave){renderSaveDialog();$('saveDialog').showModal();}
if(document.modelContext?.registerTool){const life=new AbortController();const tools=[{name:'read_battle',description:'Read units, facing angles, phase completion and current movement state.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>JSON.parse(JSON.stringify(state))},{name:'roll_battle_dice',description:'Roll independent D6 in the dice tray and battlefield HUD. Does not perform a march test.',inputSchema:{type:'object',properties:{count:{type:'integer',minimum:1,maximum:20}},required:['count'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||Object.keys(input).some(k=>k!=='count'))throw Error('Expected only count.');const dice=await animatedRoll(input.count,'Free roll');showDice(dice,'Free roll');return {dice,total:dice.reduce((a,b)=>a+b,0)};}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:life.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>life.abort(),{once:true});}
